'use strict';
// Generated schedule table, viewport behavior, validation display, and cell editing.
function scheduleViewControls(){return '<div class="schedule-view-toolbar"><div class="toolbar"><button type="button" id="schedule-fit" aria-pressed="'+scheduleFit+'">縦を全体表示</button><button type="button" id="schedule-zoom" aria-pressed="'+(!scheduleFit)+'">文字を大きくする</button><button type="button" id="schedule-expand" class="primary" aria-pressed="'+scheduleExpanded+'">'+(scheduleExpanded?'通常画面に戻る':'表を画面いっぱいに表示')+'</button></div><span id="schedule-view-status" class="subtle" role="status">'+(scheduleFit?'全職員と人数集計を縦に表示。日付は横にスクロールできます':'拡大表示：スクロールして編集できます')+'</span></div>';}
function fitHeightScale(height,tableHeight){if([height,tableHeight].some(v=>!Number.isFinite(v)||v<=0))return 1;return Math.min(1,height/tableHeight);}
function fitWidthForScale(naturalWidth,viewportWidth,scale){if(!Number.isFinite(naturalWidth)||naturalWidth<=0||!Number.isFinite(viewportWidth)||viewportWidth<=2||!Number.isFinite(scale)||scale<=0)return naturalWidth;return Math.ceil(Math.max(naturalWidth,(viewportWidth-2)/scale)+420);}
function fitScheduleTable(){
 const viewport=$('#schedule-viewport'),canvas=$('#schedule-canvas');
 if(tab!=='schedule'||!mo().generated||!viewport||!canvas)return;
 canvas.style.zoom='';canvas.style.width='';
 if(!scheduleFit)return;
 const naturalWidth=810+n()*62,viewportWidth=Number.isFinite(viewport.clientWidth)?viewport.clientWidth:0,availableHeight=Math.max(1,viewport.clientHeight-2);
 canvas.style.width=naturalWidth+'px';
 let height=canvas.offsetHeight;if(!height)return;
 let scale=fitHeightScale(availableHeight,height);
 canvas.style.width=fitWidthForScale(naturalWidth,viewportWidth,scale)+'px';
 height=canvas.offsetHeight;if(!canvas.offsetWidth||!height)return;
 scale=fitHeightScale(availableHeight,height);
 canvas.style.width=fitWidthForScale(naturalWidth,viewportWidth,scale)+'px';
 canvas.style.zoom=String(scale);
 viewport.scrollTop=0;
 $('#schedule-view-status').textContent='縦を全体表示 '+Math.round(scale*100)+'%｜日付は横スクロールできます。セルをクリックして編集'+(scale<0.7?'。文字が小さい場合は画面いっぱいに表示、または文字を大きくするを選んでください。':'');
}
function queueScheduleFit(){if(window.requestAnimationFrame){if(queueScheduleFit.frame)window.cancelAnimationFrame(queueScheduleFit.frame);queueScheduleFit.frame=window.requestAnimationFrame(fitScheduleTable);}else setTimeout(fitScheduleTable,0);}
function bindScheduleView(){
 $('#schedule-fit').onclick=()=>{scheduleFit=true;render();$('#schedule-fit').focus({preventScroll:true});};
 $('#schedule-zoom').onclick=()=>{scheduleFit=false;render();$('#schedule-zoom').focus({preventScroll:true});};
 $('#schedule-expand').onclick=()=>{scheduleExpanded=!scheduleExpanded;render();$('#schedule-expand').focus({preventScroll:true});};
 if(typeof ResizeObserver!=='undefined'){scheduleResizeObserver=new ResizeObserver(queueScheduleFit);scheduleResizeObserver.observe($('#schedule-viewport'));}
 queueScheduleFit();
}
window.addEventListener('resize',queueScheduleFit);
document.fonts?.ready.then(queueScheduleFit);
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&scheduleExpanded&&!dialog.open&&!$('#confirm').open){scheduleExpanded=false;render();$('#schedule-expand')?.focus({preventScroll:true});}});

function renderSchedule(){const m=mo();if(!m.generated){content.innerHTML=scheduleRequestPanel()+'<div class="panel empty"><h2>月の条件を入力したら、シフト案を作成</h2><p>希望休を確保し、設定した配置人数を満たす組み合わせを探します。</p><button class="primary" id="generate">シフト案を作る</button> <button id="edit-month-settings">作成条件を確認する</button></div>';$('#generate').onclick=startGenerate;$('#edit-month-settings').onclick=()=>{tab='members';render();};bindRequestControls();return;}
 const issues=E.validate(state,current),bad=new Set(issues.filter(x=>x.id&&x.d).map(x=>k(x.id,x.d))),missing=issues.filter(x=>x.type==='coverage').length;
 content.innerHTML=`${scheduleRequestPanel()}<div class="stats"><div class="stat"><span>登録された希望</span><strong>${Object.keys(m.requests).length}</strong><small> 日分</small></div><div class="stat"><span>固定した勤務</span><strong>${Object.values(m.locks).filter(Boolean).length}</strong><small> セル</small></div><div class="stat warn"><span>人数の過不足</span><strong>${missing}</strong><small> 項目</small></div><div class="stat warn"><span>その他の要確認</span><strong>${issues.length-missing}</strong><small> 項目</small></div></div><div class="panel schedule-panel" id="schedule-panel"><div class="panel-head"><div><h2>${current.replace('-','年')}月のシフト案</h2><p class="desc">セルをクリックして変更。固定した勤務は再作成しても保持されます。</p></div><div class="toolbar schedule-actions">${undoBar()}<button id="generate">再作成</button><button id="to-counts">表の下の人数を見る</button><button id="to-requests">希望休を入力</button><button id="export-csv">CSV出力</button><button id="print-schedule" type="button">印刷</button></div></div><div class="legend">${Object.keys(E.shifts).map(c=>`<span class="chip ${chip(c)}">${c} ${E.shifts[c].label}</span>`).join('')}<span>● 固定 ／ 下線 希望あり ／ 赤枠 要確認</span></div>${scheduleViewControls()}<div class="grid-wrap schedule-viewport ${scheduleFit?'is-fit':'is-zoom'}" id="schedule-viewport" style="--schedule-days:${n()}"><div id="schedule-canvas"><table class="schedule-grid" aria-label="職員のシフトと日別・勤務記号別人数"><colgroup><col class="schedule-name-col"><col span="${n()}" class="schedule-day-col"><col span="3" class="schedule-meta-col"></colgroup><thead><tr><th>職員</th>${headerDays()}<th>時間 / 目安</th><th>夜勤</th><th>休日</th></tr></thead><tbody>${state.members.map(p=>{const codes=range().map(d=>m.schedule[k(p.id,d)]||''),hours=codes.reduce((v,c)=>v+(E.shifts[c]?.hours||0),0);return `<tr>${staffRow(p,true)}${codes.map((c,i)=>{const d=i+1,id=k(p.id,d);return `<td><button class="cell ${chip(c)} ${m.locks[id]?'locked':''} ${m.requests[id]?'marked':''} ${bad.has(id)?'issue':''} ${!E.active(p,current,d)?'unavailable':''}" data-edit="${p.id}" data-date="${d}" aria-label="${esc(p.name)} ${d}日 ${esc(c||'未入力')}" title="${esc(E.shifts[c]?.label||'未入力')}${m.requests[id]?'・希望登録あり':''}">${c||'—'}</button></td>`;}).join('')}<td>${hours} / ${E.target(p,m,n())}${E.targetModeLabel(p)}</td><td>${codes.filter(c=>c==='D').length}</td><td>${codes.filter(c=>c==='E').length}</td></tr>`;}).join('')}</tbody>${countsRows()}${equivalentFooter(3)}</table></div></div>${equivalentNote()}<p class="subtle">夜勤はD＋翌日dとして集計します。時間の目安には有休を含み、「以上／以内」は職員情報の設定を使います。I勤務者は月9日の休日Eを確認します。</p><p class="subtle">勤務記号別の人数は在籍期間内の職員を1人ずつ集計します。Dとd、Bと/B、Cと/Cは別に数えます。法定配置や時間帯別の人数を判定する表ではありません。</p></div><div class="panel"><div class="panel-head"><h2>確認する項目 ${issues.length}件</h2><span class="subtle">編集すると即時更新します</span></div><div class="issue-list">${issues.map((x,i)=>`<button class="issue-link" data-issue="${i}">${esc(x.text)}</button>`).join('')||'<span>登録した条件に対する警告はありません。</span>'}</div><p class="subtle">チェック対象は画面で設定した条件です。資格別配置、法定基準、月をまたぐ連勤の完全な判定は本番導入時に追加します。</p></div>`;
 bindRequestControls();$('#to-counts').onclick=()=>$('#daily-counts').scrollIntoView({block:'start',behavior:'smooth'});$('#to-requests').onclick=()=>{$('#schedule-request-panel').scrollIntoView({block:'start',behavior:'smooth'});$('#request-person').focus({preventScroll:true});};
 document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>editCell(b.dataset.edit,+b.dataset.date));document.querySelectorAll('[data-issue]').forEach(b=>b.onclick=()=>{const x=issues[+b.dataset.issue];if(x.id&&x.d)editCell(x.id,x.d);else if(x.d)document.querySelector(`[data-date="${x.d}"]`)?.scrollIntoView({block:'center',inline:'center',behavior:'smooth'});else memberForm(x.id);});$('#generate').onclick=startGenerate;$('#export-csv').onclick=exportCSV;$('#print-schedule').onclick=printSchedule;bindScheduleView();
}
function shiftedScheduleDate(month,day,offset){let targetMonth=month,targetDay=day+offset;while(targetDay>E.days(targetMonth)){targetDay-=E.days(targetMonth);targetMonth=E.nextMonth(targetMonth);}return {month:targetMonth,day:targetDay};}
function scheduleCode(id,position){return state.months[position.month]?.schedule?.[k(id,position.day)]||'';}
function targetLimitForPositions(person,positions,codes){const months=[...new Set(positions.map(position=>position.month))];for(const month of months){const changes=positions.map((position,i)=>({position,code:codes[i]})).filter(item=>item.position.month===month).map(item=>[item.position.day,item.code]),issue=E.targetLimitIssue(state,month,person,changes);if(issue)return issue;}return '';}
function incomingShiftIssue(person,positions,codes){
 for(let i=0;i<positions.length;i++){const position=positions[i],code=codes[i],record=state.months[position.month],date=E.iso(position.month,position.day),request=record?.requests?.[k(person.id,position.day)];
  if(!E.active(person,position.month,position.day))return `${person.name}：${date}は在籍期間外です。`;
  if(!E.memberShiftAllowed(person,code))return `${person.name}：${date}の${code||'空欄'}は勤務区分に合いません。`;
  if(code==='D'&&!person.night)return `${person.name}は夜勤不可のため、Dを担当できません。`;
  if(E.works(code)&&code!=='d'&&!person.weekdays.includes(E.weekday(position.month,position.day)))return `${person.name}：${date}は勤務不可の曜日です。`;
  if(person.role==='管理者'&&(record?.meetings||[]).includes(position.day)&&code!=='B')return `${person.name}：${date}は会議日のB勤務が必要です。`;
  if(request&&request!=='W'&&request!==code)return `${person.name}：${date}の希望と${code||'空欄'}が重なります。`;
  if(code==='F'&&!E.paidLeaveEligibility(person,date).allowed)return `${person.name}：${date}は有給を利用できません。`;
 }return targetLimitForPositions(person,positions,codes);
}
function swapNightSequence(first,second,startDay){
 const positions=[0,1,2].map(offset=>shiftedScheduleDate(current,startDay,offset)),expected=['D','d','E'],firstCodes=positions.map(position=>scheduleCode(first.id,position)),secondCodes=positions.map(position=>scheduleCode(second.id,position)),firstStarts=firstCodes[0]==='D',secondStarts=secondCodes[0]==='D';
 if(!firstStarts&&!secondStarts)return false;
 if(firstStarts&&secondStarts){toast('どちらも夜勤Dのため、担当交代は不要です。');return true;}
 const owner=firstStarts?first:second,replacement=firstStarts?second:first,ownerCodes=firstStarts?firstCodes:secondCodes,replacementCodes=firstStarts?secondCodes:firstCodes;
 for(let i=0;i<positions.length;i++){const position=positions[i],record=state.months[position.month],actual=ownerCodes[i],uncreatedFuture=position.month!==current&&!record?.generated&&!actual;if(actual!==expected[i]&&!uncreatedFuture){toast('現在のD・d・Eが3日連続になっていないため、先にシフトを確認してください。');return true;}}
 for(const position of positions){const code=scheduleCode(replacement.id,position),required=E.requiredNightShift(state,position.month,replacement,position.day);if(['D','d'].includes(code)||required){toast('交代する職員の3日間に別の夜勤セットがあります。別の職員を選んでください。');return true;}if(state.months[position.month]?.locks?.[k(replacement.id,position.day)]){toast('交代する職員の3日間に固定勤務があります。先に固定を解除してください。');return true;}}
 const replacementNightCount=Object.entries(state.months[current]?.schedule||{}).filter(([cell,code])=>cell.startsWith(replacement.id+':')&&code==='D').length;if(replacementNightCount>=replacement.nightMax){toast(`${replacement.name}は夜勤上限に達しているため交代できません。`);return true;}
 let issue=incomingShiftIssue(replacement,positions,expected)||incomingShiftIssue(owner,positions,replacementCodes);if(issue){toast(issue);return true;}
 change(()=>{for(let i=0;i<positions.length;i++){const position=positions[i],record=E.month(state,position.month),ownerCell=k(owner.id,position.day),replacementCell=k(replacement.id,position.day),ownerCode=replacementCodes[i];record.schedule[ownerCell]=ownerCode;record.schedule[replacementCell]=expected[i];if(ownerCode)record.locks[ownerCell]=true;else delete record.locks[ownerCell];record.locks[replacementCell]=true;}});close();toast(`${replacement.name}へD・d・Eの3日間をまとめて交代しました。`);return true;
}
function editCell(id,d){const p=state.members.find(x=>x.id===id),m=mo(),cell=k(id,d),c=m.schedule[cell]||'';dialog.innerHTML=`<div class="dialog-head"><div><span class="subtle">${current.replace('-','年')}月${d}日（${'日月火水木金土'[E.weekday(current,d)]}）</span><h2>${esc(p.name)}</h2></div><button class="close" aria-label="閉じる">×</button></div>${p.role==='管理者'&&E.active(p,current,d)&&E.meetingDays(state,current).includes(d)?'<div class="note">会議日です。管理者はB勤務が必要です。B以外に変更すると要確認として表示します。</div>':''}${m.requests[cell]?`<div class="note">この日は${m.requests[cell]==='W'?'出勤希望':m.requests[cell]==='E'?'希望休':'有給希望'}です。変更した場合は要確認として表示します。</div>`:''}<p class="desc">現在：${c?`${c} ${E.shifts[c].label}`:'未入力'}　変更する勤務を選んでください。</p><div class="choices">${Object.entries(E.shifts).filter(([v])=>E.memberShiftAllowed(p,v)).map(([v,s])=>`<button class="choice ${s.cls}" data-choice="${v}"><strong>${v} ${s.label}</strong><small>${s.time||'勤務なし'}</small></button>`).join('')}</div><label><input id="lock-edit" type="checkbox" checked> 変更後のセルを固定する</label><p class="note">Dを選ぶと、翌日d・翌々日Eも必ず設定されます。</p><div class="fields"><label class="field">同じ日の勤務を交換する<select id="swap-person"><option value="">交換相手を選択</option>${options(state.members.filter(x=>x.id!==id&&E.active(x,current,d)).map(x=>[x.id,`${x.name}：${m.schedule[k(x.id,d)]||'未入力'}`]),'')}</select></label><button id="swap">勤務を交換</button></div><div class="dialog-bottom"><button id="unlock">${m.locks[cell]?'固定を解除':'現在の勤務を固定'}</button><button id="empty-cell">空欄にする</button><button class="primary close-action">閉じる</button></div>`;dialog.showModal();dialog.querySelector('.close').onclick=close;dialog.querySelector('.close-action').onclick=close;
 dialog.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{const v=b.dataset.choice,fix=$('#lock-edit').checked,patches=[[d,v]],requiredHere=E.requiredNightShift(state,current,p,d);if(requiredHere&&v!==requiredHere)return toast(`前日までの夜勤により、この日は${requiredHere}が必要です。`);if(v==='F'){const eligibility=E.paidLeaveEligibility(p,E.iso(current,d));if(!eligibility.allowed)return toast(eligibility.reason);}if(v==='D'){for(const[offset,required]of [[1,'d'],[2,'E']]){const conflict=E.requiredShiftConflict(state,current,p,d+offset,required);if(conflict)return toast(conflict+'。勤務を先に調整してください。');if(d+offset<=n())patches.push([d+offset,required]);}}const limitIssue=v==='D'?targetLimitForPositions(p,[0,1,2].map(offset=>shiftedScheduleDate(current,d,offset)),['D','d','E']):E.targetLimitIssue(state,current,p,patches);if(limitIssue)return toast(limitIssue);change(()=>{for(const[day,code]of patches){m.schedule[k(id,day)]=code;if(fix)m.locks[k(id,day)]=true;else delete m.locks[k(id,day)];}});close();toast('勤務を変更しました');});
 $('#unlock').onclick=()=>{change(()=>m.locks[cell]?delete m.locks[cell]:m.locks[cell]=true);close();};$('#empty-cell').onclick=()=>{const required=E.requiredNightShift(state,current,p,d);if(required)return toast(`前日までの夜勤により、この日は${required}が必要です。`);change(()=>{m.schedule[cell]='';m.locks[cell]=true;});close();};$('#swap').onclick=()=>{const other=$('#swap-person').value;if(!other)return toast('交換相手を選んでください');const otherPerson=state.members.find(x=>x.id===other),q=k(other,d),mine=m.schedule[cell]||'',theirs=m.schedule[q]||'',mineRequired=E.requiredNightShift(state,current,p,d),otherRequired=E.requiredNightShift(state,current,otherPerson,d);if(mine==='D'||theirs==='D'){if(swapNightSequence(p,otherPerson,d))return;}if(mine==='d'||theirs==='d'||mineRequired||otherRequired)return toast('dまたは夜勤セットのEだけを途中交代することはできません。Dの日から3日間まとめて交代してください。');if(m.locks[q])return toast('交換相手の勤務は固定されています。先に解除してください。');if(!E.memberShiftAllowed(p,theirs)||!E.memberShiftAllowed(otherPerson,mine))return toast('雇用区分・I勤務・夜勤条件に合わないため交換できません。');if(theirs==='F'&&!E.paidLeaveEligibility(p,E.iso(current,d)).allowed||mine==='F'&&!E.paidLeaveEligibility(otherPerson,E.iso(current,d)).allowed)return toast('有給を利用できない職員が含まれるため交換できません。');const limitIssue=E.targetLimitIssue(state,current,p,[[d,theirs]])||E.targetLimitIssue(state,current,otherPerson,[[d,mine]]);if(limitIssue)return toast(limitIssue);change(()=>{[m.schedule[cell],m.schedule[q]]=[theirs,mine];m.locks[cell]=true;m.locks[q]=true;});close();toast('勤務を交換しました。要確認の項目を確認してください。');};
}
